use std::net::{TcpListener,TcpStream};use std::io::{Read,Write};use std::sync::{Arc,atomic::{AtomicUsize,AtomicBool,Ordering}};use std::time::{Duration,Instant};use std::thread;
#[test]fn many_incomplete_clients_then_recovery(){let l=TcpListener::bind("127.0.0.1:0").unwrap();let addr=l.local_addr().unwrap();l.set_nonblocking(true).unwrap();let stop=Arc::new(AtomicBool::new(false));let active=Arc::new(AtomicUsize::new(0));let st=stop.clone();let ac=active.clone();let server=thread::spawn(move||{while !st.load(Ordering::Relaxed){match l.accept(){Ok((mut s,_))=>{let now=Instant::now();if ac.fetch_add(1,Ordering::Relaxed)>=8192{ac.fetch_sub(1,Ordering::Relaxed);continue}let a=ac.clone();if thread::Builder::new().stack_size(131072).spawn(move||{let mut temp=[0u8;4096];let mut buf=Vec::new();loop{let rem=match Duration::from_secs(5).checked_sub(now.elapsed()){Some(r) if !r.is_zero()=>r,_=>break};let _=s.set_read_timeout(Some(rem));match s.read(&mut temp){Ok(0)|Err(_)=>break,Ok(n)=>buf.extend_from_slice(&temp[..n])}if buf.windows(4).any(|w|w==b"\r\n\r\n"){let _=s.write_all(b"ok");break}}a.fetch_sub(1,Ordering::Relaxed);}).is_err(){ac.fetch_sub(1,Ordering::Relaxed);}},Err(e)if e.kind()==std::io::ErrorKind::WouldBlock=>thread::sleep(Duration::from_millis(1)),Err(_)=>break}}});let mut clients=Vec::with_capacity(2048);for _ in 0..2048{let mut s=TcpStream::connect(addr).unwrap();let _=s.write_all(b"GET /hello");clients.push(s);}let end=Instant::now()+Duration::from_millis(500);while active.load(Ordering::Relaxed)<2048&&Instant::now()<end{thread::sleep(Duration::from_millis(1));}let n=active.load(Ordering::Relaxed);let mut s=TcpStream::connect(addr).unwrap();s.set_read_timeout(Some(Duration::from_millis(500))).unwrap();s.write_all(b"GET /hello HTTP/1.1\r\n\r\n").unwrap();let mut reply=[0;2];let response=s.read_exact(&mut reply);drop(clients);stop.store(true,Ordering::Relaxed);server.join().unwrap();assert!(response.is_ok()&&reply==*b"ok","{n} active; subsequent response {:?}",response);}
